// Authored example: hide one slide of a three-slide deck, then read every slide's hidden flag back after a save and reload
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import org.aspose.slides.foss.ISlide;
import org.aspose.slides.foss.Presentation;
import org.aspose.slides.foss.export.SaveFormat;

public class HiddenSlideRoundtripExample {
    public static void main(String[] args) throws Exception {
        ByteArrayOutputStream savedBytes = new ByteArrayOutputStream();
        try (Presentation pres = new Presentation()) {
            pres.getSlides().addEmptySlide(pres.getLayoutSlides().get(0));
            pres.getSlides().addEmptySlide(pres.getLayoutSlides().get(0));
            pres.getSlides().get(1).setHidden(true);
            pres.save(savedBytes, SaveFormat.PPTX);
        }

        try (Presentation reloaded = new Presentation(new ByteArrayInputStream(savedBytes.toByteArray()))) {
            int count = reloaded.getSlides().size();
            System.out.println("slides: " + count);
            if (count != 3) {
                throw new AssertionError("expected 3 slides after reload, found " + count);
            }
            for (int i = 0; i < count; i++) {
                ISlide slide = reloaded.getSlides().get(i);
                System.out.println("slide " + (i + 1) + " hidden: " + slide.isHidden());
            }
            if (reloaded.getSlides().get(0).isHidden()) {
                throw new AssertionError("expected slide 1 to stay visible");
            }
            if (!reloaded.getSlides().get(1).isHidden()) {
                throw new AssertionError("expected slide 2 to be hidden after reload");
            }
            if (reloaded.getSlides().get(2).isHidden()) {
                throw new AssertionError("expected slide 3 to stay visible");
            }
        }
    }
}
