Adds two named rectangles and a bent connector on one slide, joins the connector's start and end to them with setStartShapeConnectedTo and setEndShapeConnectedTo, saves the presentation to memory, reloads it and reads back the names of the shapes the connector starts and ends at.

Example:
// Authored example: connect two shapes with a connector, then read the connection back after a save and reload
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import org.aspose.slides.foss.IAutoShape;
import org.aspose.slides.foss.IConnector;
import org.aspose.slides.foss.IShape;
import org.aspose.slides.foss.ISlide;
import org.aspose.slides.foss.Presentation;
import org.aspose.slides.foss.ShapeType;
import org.aspose.slides.foss.export.SaveFormat;

public class ConnectorRoundtripExample {
    public static void main(String[] args) throws Exception {
        ByteArrayOutputStream savedBytes = new ByteArrayOutputStream();
        try (Presentation pres = new Presentation()) {
            ISlide slide = pres.getSlides().get(0);
            slide.getShapes().clear();
            IAutoShape source = slide.getShapes().addAutoShape(ShapeType.RECTANGLE, 50, 50, 100, 60);
            source.setName("SourceBox");
            IAutoShape target = slide.getShapes().addAutoShape(ShapeType.RECTANGLE, 350, 200, 100, 60);
            target.setName("TargetBox");
            IConnector connector = slide.getShapes().addConnector(ShapeType.BENT_CONNECTOR3, 0, 0, 1, 1);
            connector.setStartShapeConnectedTo(source);
            connector.setEndShapeConnectedTo(target);
            pres.save(savedBytes, SaveFormat.PPTX);
        }

        try (Presentation reloaded = new Presentation(new ByteArrayInputStream(savedBytes.toByteArray()))) {
            IConnector found = null;
            for (IShape shape : reloaded.getSlides().get(0).getShapes().toArray()) {
                if (shape instanceof IConnector) {
                    found = (IConnector) shape;
                }
            }
            if (found == null) {
                throw new AssertionError("expected the reloaded slide to hold a connector");
            }
            String startName = found.getStartShapeConnectedTo().getName();
            String endName = found.getEndShapeConnectedTo().getName();
            System.out.println("start: " + startName);
            System.out.println("end: " + endName);
            if (!"SourceBox".equals(startName)) {
                throw new AssertionError("expected the connector to start at SourceBox, found " + startName);
            }
            if (!"TargetBox".equals(endName)) {
                throw new AssertionError("expected the connector to end at TargetBox, found " + endName);
            }
        }
    }
}
