// Authored example: remove the middle slide of a three-slide deck and confirm the remaining order after a save and reload
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import org.aspose.slides.foss.IAutoShape;
import org.aspose.slides.foss.ISlide;
import org.aspose.slides.foss.Presentation;
import org.aspose.slides.foss.ShapeType;
import org.aspose.slides.foss.export.SaveFormat;

public class SlideRemovalRoundtripExample {
    public static void main(String[] args) throws Exception {
        ByteArrayOutputStream savedBytes = new ByteArrayOutputStream();
        try (Presentation pres = new Presentation()) {
            pres.getSlides().removeAt(0);
            String[] labels = {"Intro", "Draft", "Summary"};
            for (String label : labels) {
                ISlide slide = pres.getSlides().addEmptySlide(pres.getLayoutSlides().get(0));
                IAutoShape marker = slide.getShapes().addAutoShape(ShapeType.RECTANGLE, 50, 50, 200, 60);
                marker.addTextFrame(label);
            }
            pres.getSlides().removeAt(1);
            pres.save(savedBytes, SaveFormat.PPTX);
        }

        try (Presentation reloaded = new Presentation(new ByteArrayInputStream(savedBytes.toByteArray()))) {
            int count = reloaded.getSlides().size();
            System.out.println("slides: " + count);
            if (count != 2) {
                throw new AssertionError("expected 2 slides after removing one, found " + count);
            }
            String first = ((IAutoShape) reloaded.getSlides().get(0).getShapes().get(0)).getTextFrame().getText();
            String second = ((IAutoShape) reloaded.getSlides().get(1).getShapes().get(0)).getTextFrame().getText();
            System.out.println("first: " + first);
            System.out.println("second: " + second);
            if (!"Intro".equals(first)) {
                throw new AssertionError("expected the first remaining slide to be Intro, found " + first);
            }
            if (!"Summary".equals(second)) {
                throw new AssertionError("expected the second remaining slide to be Summary, found " + second);
            }
        }
    }
}
